function formatMetric(value, digits = 4) {
  return Number(value).toFixed(digits);
}

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function maybeNumber(value) {
  if (value === undefined || value === null || String(value).trim() === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

async function fetchText(path) {
  const response = await fetch(path, { cache: "no-store" });
  if (!response.ok) throw new Error(`Cannot load ${path}`);
  return response.text();
}

function parseCsv(text) {
  const rows = [];
  let field = "";
  let row = [];
  let quoted = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];
    if (char === '"' && quoted && next === '"') {
      field += '"';
      i += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === "," && !quoted) {
      row.push(field);
      field = "";
    } else if ((char === "\n" || char === "\r") && !quoted) {
      if (char === "\r" && next === "\n") i += 1;
      row.push(field);
      if (row.some((item) => item !== "")) rows.push(row);
      field = "";
      row = [];
    } else {
      field += char;
    }
  }
  if (field || row.length) {
    row.push(field);
    rows.push(row);
  }

  const headers = rows.shift() || [];
  return rows.map((values) => Object.fromEntries(headers.map((header, index) => [header, values[index] ?? ""])));
}

async function loadLiveData() {
  try {
    const [benchmarkText, leaderboardText, figureResponse] = await Promise.all([
      fetchText(dataSources.benchmark),
      fetchText(dataSources.leaderboard),
      fetch(dataSources.figures, { cache: "no-store" }),
    ]);
    benchmarkRows = parseCsv(benchmarkText);
    liveLeaderboardRows = parseCsv(leaderboardText);
    figureManifest = figureResponse.ok ? await figureResponse.json() : [];
  } catch (error) {
    benchmarkRows = [];
    liveLeaderboardRows = [];
    figureManifest = [];
  }
}

function familyKeyFromCategory(category) {
  if (category === "classical_descriptor") return "classical";
  if (category === "classical_graph") return "graph";
  if (category === "hybrid_quantum_descriptor") return "hybrid";
  if (category === "quantum_graph") return "quantumGraph";
  return "quantum";
}

function modelLabelFromRow(row) {
  const base = row.model === "hybrid_qhead" ? "Hybrid QHead" : (row.model || "").toUpperCase();
  const q = row.n_qubits ? ` q${row.n_qubits}` : "";
  const d = row.circuit_depth ? `-d${row.circuit_depth}` : "";
  return `${base}${q}${d}`;
}

function getLeaderboardRowsForTask(task) {
  if (liveLeaderboardRows.length) {
    return liveLeaderboardRows
      .filter((row) => row.task === task)
      .sort((a, b) => toNumber(a.rank_in_task) - toNumber(b.rank_in_task))
      .map((row) => [
        modelLabelFromRow(row),
        familyKeyFromCategory(row.category),
        toNumber(row.auroc_mean),
        toNumber(row.primary_metric_std),
        toNumber(row.balanced_accuracy_mean),
        toNumber(row.f1_mean),
        row,
      ]);
  }
  return leaderboard[task];
}

function getBenchmarkRows({ task, model, category } = {}) {
  return benchmarkRows.filter((row) => {
    if (task && row.task !== task) return false;
    if (model && row.model !== model) return false;
    if (category && row.category !== category) return false;
    return true;
  });
}

function quantumModelLabel(model) {
  return quantumRunModels.find((item) => item.key === model)?.label || modelLabelFromRow({ model });
}

function quantumModelColor(model) {
  return quantumRunModels.find((item) => item.key === model)?.color || "#7ee6ff";
}

function quantumMetricValue(row) {
  return toNumber(row?.primary_metric_mean || row?.auroc_mean);
}

function quantumMetricStd(row) {
  return toNumber(row?.primary_metric_std || row?.auroc_std);
}

function quantumDataFraction(row) {
  const direct = maybeNumber(row?.data_fraction);
  if (direct !== null && direct > 0 && direct < 1) return direct;
  const match = String(row?.experiment_id || "").match(/frac([0-9;]+)/);
  if (!match) return null;
  const inferred = Number(match[1]);
  return Number.isFinite(inferred) && inferred > 0 && inferred < 1 ? inferred : null;
}

function quantumExperimentKey(row, index = 0) {
  return row?.experiment_id || [
    row?.task || selectedQuantumRunTask,
    row?.model || selectedQuantumRunModel,
    row?.n_qubits || "q",
    row?.circuit_depth || "d",
    quantumDataFraction(row) ?? "full",
    index,
  ].join("-");
}

function quantumExperimentLabel(row) {
  const q = row?.n_qubits || "-";
  const depth = row?.circuit_depth || "-";
  const fraction = quantumDataFraction(row);
  return fraction ? `q${q}-d${depth} f${fraction}` : `q${q}-d${depth}`;
}

function quantumExperimentMeta(row) {
  const parts = [
    tx(categoryLabels[row?.category] || row?.category || "kuantum"),
    quantumDataFraction(row) ? `${tx("Veri fraksiyonu")} ${quantumDataFraction(row)}` : tx("Tüm veri"),
    `${tx("Seed")} ${row?.seed_count || "-"}`,
  ];
  return parts.join(" · ");
}

function getQuantumRunRows({ task = selectedQuantumRunTask, model = selectedQuantumRunModel } = {}) {
  const source = benchmarkRows.length ? benchmarkRows : liveLeaderboardRows;
  return source
    .filter((row) => row.task === task && row.model === model && row.n_qubits && row.circuit_depth)
    .sort((a, b) => quantumMetricValue(b) - quantumMetricValue(a));
}

function selectedQuantumRunRows() {
  return getQuantumRunRows({ task: selectedQuantumRunTask, model: selectedQuantumRunModel });
}

function getSelectedQuantumRunRow() {
  const rows = selectedQuantumRunRows();
  if (!rows.length) return null;
  const selectedIndex = rows.findIndex((row, index) => quantumExperimentKey(row, index) === selectedQuantumExperimentId);
  const index = selectedIndex >= 0 ? selectedIndex : 0;
  selectedQuantumExperimentId = quantumExperimentKey(rows[index], index);
  return rows[index];
}

function countLabel(count, trLabel, enSingular, enPlural = `${enSingular}s`) {
  return currentLanguage === "en" ? `${count} ${count === 1 ? enSingular : enPlural}` : `${count} ${trLabel}`;
}

function taskLabel(task) {
  return datasets[task]?.label || task.toUpperCase();
}

function fitCanvas(canvas, heightRatio = 0.54, minHeight = 320, maxHeight = Infinity) {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = Math.max(320, rect.width);
  const height = Math.min(maxHeight, Math.max(minHeight, width * heightRatio));
  const pixelWidth = Math.floor(width * dpr);
  const pixelHeight = Math.floor(height * dpr);
  if (canvas.width !== pixelWidth) canvas.width = pixelWidth;
  if (canvas.height !== pixelHeight) canvas.height = pixelHeight;
  canvas.style.height = `${height}px`;
  const ctx = canvas.getContext("2d");
  localizeCanvasContext(ctx);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, width, height };
}

function fitFixedCanvas(canvas, minWidth = 320, minHeight = 320) {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = Math.max(minWidth, rect.width || minWidth);
  const height = Math.max(minHeight, rect.height || minHeight);
  const pixelWidth = Math.floor(width * dpr);
  const pixelHeight = Math.floor(height * dpr);
  if (canvas.width !== pixelWidth) canvas.width = pixelWidth;
  if (canvas.height !== pixelHeight) canvas.height = pixelHeight;
  const ctx = canvas.getContext("2d");
  localizeCanvasContext(ctx);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, width, height };
}

function parseClassCounts(value) {
  const result = { "0": 0, "1": 0 };
  String(value || "").replace(/([01]):\s*(\d+)/g, (_, label, count) => {
    result[label] = Number(count);
    return "";
  });
  return result;
}

function testClassStats(task) {
  const counts = parseClassCounts(datasets[task].classes.test);
  const total = counts["0"] + counts["1"];
  return {
    negative: counts["0"],
    positive: counts["1"],
    total,
    positiveRatio: total ? counts["1"] / total : 0,
  };
}

function matrixRowMatches(row, key) {
  const raw = row[6] || {};
  const model = raw.model || "";
  const name = row[0] || "";
  if (model) return model === key;
  if (key === "hybrid_qhead") return name.startsWith("Hybrid QHead");
  if (key === "qsvm") return name.startsWith("QSVM");
  if (key === "vqc") return name.startsWith("VQC");
  if (key === "qgnn") return name.startsWith("QGNN");
  return name === key.toUpperCase() || name.startsWith(`${key.toUpperCase()} `);
}

function bestMatrixCell(task, modelKey) {
  const candidates = getLeaderboardRowsForTask(task)
    .filter((row) => matrixRowMatches(row, modelKey))
    .sort((a, b) => b[2] - a[2]);
  return candidates[0] || null;
}

function matrixCells() {
  return taskOrder.flatMap((task) => experimentMatrixModels.map((model) => ({
    task,
    model,
    row: bestMatrixCell(task, model.key),
  })));
}

function modelShortLabel(name, max = 18) {
  const label = String(name || "").replace("Hybrid QHead", "HQ");
  return label.length > max ? `${label.slice(0, max - 1)}…` : label;
}

